package securityreview_test

import (
	"context"
	"fmt"
	stdhttp "net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/weiloon1234/Foundry-Go/auth"
	"github.com/weiloon1234/Foundry-Go/contract"
	"github.com/weiloon1234/Foundry-Go/database/codec"
	http "github.com/weiloon1234/Foundry-Go/http"
	"github.com/weiloon1234/Foundry-Go/httpclient"
	"github.com/weiloon1234/Foundry-Go/model"
	"github.com/weiloon1234/Foundry-Go/secret"
	"github.com/weiloon1234/Foundry-Go/value"
)

type Account struct{ ID int64 }

func (a Account) reference() model.Reference[Account, int64] {
	return model.NewReference[Account]("audit_accounts", a.ID, codec.Signed[int64]())
}
func (a Account) FoundryIdentity() (model.Identity, error) { return a.reference().Identity() }
func TestAuditCookieAuthenticationCacheHeaders(t *testing.T) {
	provider := auth.DefineProvider("audit.accounts", (Account{}).reference(), func(_ context.Context, id int64) (value.Optional[Account], error) { return value.Set(Account{id}), nil }, func(context.Context, Account) (bool, error) { return true, nil })
	strategy := auth.DefineStrategy("audit.cookie", func(_ context.Context, s secret.String) (value.Optional[auth.Proof[Account, int64]], error) {
		var id int64
		switch s.Reveal() {
		case "alice-fixture":
			id = 1
		case "bob-fixture":
			id = 2
		default:
			return value.Optional[auth.Proof[Account, int64]]{}, nil
		}
		proof, err := auth.NewProof(Account{id}.reference(), auth.Authenticated)
		return value.Set(proof), err
	})
	guard := auth.DefineGuard("audit.web", provider, strategy)
	registry, err := auth.NewRegistry(auth.DefaultConfig(), guard.Registration())
	if err != nil {
		t.Fatal(err)
	}
	cookie := http.DefineCookie("audit_session", http.SecretCookie(), http.DefaultCookieOptions())
	transport, err := http.NewCookieAuthentication(registry, http.CSRFConfig{}, http.CookieCredential("audit.cookie", cookie))
	if err != nil {
		t.Fatal(err)
	}
	route := http.DefineRoute(http.RouteSpec{ID: "audit.profile", Method: http.GET, Access: http.Guarded}, http.StaticPath("/profile"))
	secured := http.RequireRouteAuthentication(route, transport, guard)
	router, err := http.NewRouter(secured.HandleRaw(func(w stdhttp.ResponseWriter, r *stdhttp.Request, a Account, _ http.NoPath) {
		w.Header().Set("Content-Type", "text/plain")
		w.Header().Set("Last-Modified", "Tue, 01 Sep 2026 00:00:00 GMT")
		fmt.Fprintf(w, "account-%d", a.ID)
	}))
	if err != nil {
		t.Fatal(err)
	}
	typedRoute := http.DefineRoute(http.RouteSpec{ID: "audit.typed_profile", Method: http.GET, Access: http.Guarded}, http.StaticPath("/typed-profile"))
	endpoint := http.DefineEndpoint(typedRoute, http.EmptyQuery(), http.EmptyBody(), http.JSONResponse(200, contract.StringJSON[string]()))
	typedRouter, err := http.NewRouter(http.RequireAuthentication(endpoint, transport, guard).Handle(func(_ context.Context, a Account, _ http.Input[http.NoPath, http.NoQuery, http.NoBody]) (string, error) {
		return fmt.Sprintf("account-%d", a.ID), nil
	}))
	if err != nil {
		t.Fatal(err)
	}
	for _, transportCase := range []struct {
		name, path string
		router     stdhttp.Handler
		json       bool
	}{{"raw", "/profile", router, false}, {"typed", "/typed-profile", typedRouter, true}} {
		for i, credential := range []string{"alice-fixture", "bob-fixture"} {
			request := httptest.NewRequest("GET", "https://audit.example"+transportCase.path, nil)
			request.AddCookie(&stdhttp.Cookie{Name: "audit_session", Value: credential})
			response := httptest.NewRecorder()
			transportCase.router.ServeHTTP(response, request)
			expected := fmt.Sprintf("account-%d", i+1)
			if transportCase.json {
				expected = fmt.Sprintf("%q", expected)
			}
			if response.Code != 200 || response.Body.String() != expected {
				t.Fatalf("actual authentication failed: status=%d", response.Code)
			}
			h := response.Header()
			if h.Get("Cache-Control") != "" || h.Get("Pragma") != "" || strings.Contains(strings.ToLower(strings.Join(h.Values("Vary"), ",")), "cookie") {
				t.Fatal("candidate cache-policy gap is not present")
			}
			t.Logf("%s user %d: status=%d body=%q Cache-Control=%q Vary=%q Last-Modified=%q", transportCase.name, i+1, response.Code, response.Body.String(), h.Get("Cache-Control"), h.Values("Vary"), h.Get("Last-Modified"))
		}
	}
}
func TestAuditOutboundURLPolicy(t *testing.T) {
	var calls int
	destination := httptest.NewServer(stdhttp.HandlerFunc(func(w stdhttp.ResponseWriter, r *stdhttp.Request) { calls++; fmt.Fprint(w, "loopback reached") }))
	defer destination.Close()
	config := httpclient.DefaultConfig("audit.generic")
	config.Retry = httpclient.NoRetries()
	client, err := httpclient.New(config, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer client.Close(context.Background())
	response, err := client.Do(t.Context(), client.Get(destination.URL))
	if err != nil {
		t.Fatal(err)
	}
	text, err := response.Text()
	if err != nil || text != "loopback reached" || calls != 1 {
		t.Fatal("loopback request was not executed")
	}
	config.Name = "audit.named"
	config.BaseURL = destination.URL
	named, err := httpclient.New(config, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer named.Close(context.Background())
	if named.Get("http://untrusted.invalid/secret").Validate() == nil {
		t.Fatal("named origin boundary unexpectedly allowed absolute URL")
	}
	t.Log("generic absolute URL reaches loopback; named client rejects another absolute origin")
}
